<?php if(in_array($section,['storage','files','user_files','folders'],true)): ?>
<form method="get" class="admin-search"><input type="hidden" name="section" value="storage"><input type="hidden" name="folder" value="0"><label for="storageOwner">瀏覽使用者雲端</label><select id="storageOwner" name="uid" required><option value="">選擇使用者</option><?php foreach(adminQuery($pdo,'SELECT user_id,username FROM users ORDER BY username')->fetchAll(PDO::FETCH_ASSOC) as $owner): ?><option value="<?= (int)$owner['user_id'] ?>" <?= $uid===(int)$owner['user_id']?'selected':'' ?>><?= ah($owner['username']) ?></option><?php endforeach; ?></select><button class="btn btn-soft">開啟</button></form>
<?php if($uid && $folder!==null): $storageOwner=adminQuery($pdo,'SELECT username FROM users WHERE user_id=?',[$uid])->fetchColumn(); ?>
<nav class="admin-storage-path" aria-label="資料夾路徑"><strong><?= ah($storageOwner) ?> 的雲端</strong><a href="<?= ah(adminUrl(['section'=>'storage','folder'=>0,'q'=>''])) ?>">我的雲端</a><?php foreach(adminFolderTrail($pdo,$uid,$folder) as $crumb): ?><span>/</span><a href="<?= ah(adminUrl(['section'=>'storage','folder'=>$crumb['folder_id'],'q'=>''])) ?>"><?= ah($crumb['folder_name']) ?></a><?php endforeach; ?></nav>
<p class="admin-total">顯示此位置的檔案與子資料夾。<a href="<?= ah(adminUrl(['section'=>'storage','folder'=>null])) ?>">查看此使用者全部項目</a></p><?php endif; endif; ?>
